#include <windows.h>
#include <shlobj.h>
#include <iostream>
#include <string>
bool locks=false,renameCommand=false;
bool packaged(){for(auto command:{std::pair{L"{49A8359C-85B9-4E7A-905E-6A724911750A}",L"文件占用"},std::pair{L"{57ABA3E6-8D9A-4A16-A717-6541B2241A36}",L"批量重命名"}}){CLSID clsid;CLSIDFromString(command.first,&clsid);IExplorerCommand* instance=nullptr;if(FAILED(CoCreateInstance(clsid,nullptr,CLSCTX_LOCAL_SERVER,IID_PPV_ARGS(&instance))))return false;PWSTR title=nullptr;EXPCMDSTATE state=ECS_HIDDEN;bool valid=SUCCEEDED(instance->GetTitle(nullptr,&title))&&title&&wcscmp(title,command.second)==0&&SUCCEEDED(instance->GetState(nullptr,FALSE,&state))&&state==ECS_ENABLED;CoTaskMemFree(title);instance->Release();if(!valid)return false;}return true;}
void inspect(HMENU menu){for(int i=0;i<GetMenuItemCount(menu);i++){wchar_t label[1024];MENUITEMINFOW item{sizeof(item)};item.fMask=MIIM_STRING|MIIM_SUBMENU;item.dwTypeData=label;item.cch=1024;if(!GetMenuItemInfoW(menu,i,TRUE,&item))continue;std::wstring title(label);if(title==L"文件占用")locks=true;if(title==L"批量重命名")renameCommand=true;if(item.hSubMenu)inspect(item.hSubMenu);}}
int wmain(int argc,wchar_t**argv){if(argc<2||argc>3)return 1;CoInitializeEx(nullptr,COINIT_APARTMENTTHREADED);PIDLIST_ABSOLUTE id=nullptr;HRESULT hr=SHParseDisplayName(argv[1],nullptr,&id,0,nullptr);if(FAILED(hr))return 2;IShellFolder* folder=nullptr;PCUITEMID_CHILD child=nullptr;hr=SHBindToParent(id,IID_PPV_ARGS(&folder),&child);if(FAILED(hr))return 3;IContextMenu* context=nullptr;hr=folder->GetUIObjectOf(nullptr,1,&child,IID_IContextMenu,nullptr,(void**)&context);if(FAILED(hr))return 4;HMENU menu=CreatePopupMenu();hr=context->QueryContextMenu(menu,0,1,32767,CMF_NORMAL);if(FAILED(hr))return 5;inspect(menu);DestroyMenu(menu);context->Release();folder->Release();CoTaskMemFree(id);bool modern=argc<3||packaged();CoUninitialize();std::cout<<"{\"locks\":"<<(locks?"true":"false")<<",\"rename\":"<<(renameCommand?"true":"false")<<"}\n";return locks&&renameCommand&&modern?0:6;}
